{
  "name": "Calculateur Moyenne Semestre",
  "description": "Une application élégante et performante pour calculer la moyenne de votre semestre universitaire avec les coefficients et pondérations spécifiques."
}

export interface ModuleConfig {
  id: string;
  name: string;
  coefficient: number;
  hasTd: boolean;
  hasTp: boolean;
}

export interface ModuleMarks {
  exam?: number;
  td?: number;
  tp?: number;
}

export interface SemesterState {
  [moduleId: string]: ModuleMarks;
}

import { ModuleConfig } from './types';

export const MODULES: ModuleConfig[] = [
  { id: 'algo', name: 'Algorithme', coefficient: 3, hasTd: true, hasTp: true },
  { id: 'anglais', name: 'Anglais', coefficient: 2, hasTd: true, hasTp: false },
  { id: 'asbgd', name: 'ASBGD', coefficient: 3, hasTd: false, hasTp: true },
  { id: 'gestion_projet', name: 'Gestion de projet', coefficient: 3, hasTd: false, hasTp: false },
  { id: 'meps', name: 'MEPS', coefficient: 3, hasTd: true, hasTp: false },
  { id: 'reseaux', name: 'Réseaux et protocoles', coefficient: 3, hasTd: false, hasTp: true },
  { id: 'se', name: 'SE', coefficient: 3, hasTd: true, hasTp: true },
];

export const WEIGHTS = {
  EXAM_FULL: 1.0,
  EXAM_WITH_BOTH: 0.6,
  TD_POND: 0.2,
  TP_POND: 0.2,
  DUO_POND_SECONDARY: 0.4
};

import { ModuleConfig, ModuleMarks } from './types';
import { WEIGHTS } from './constants';

export const calculateModuleAverage = (config: ModuleConfig, marks: ModuleMarks): number => {
  const e = marks.exam || 0;
  const d = marks.td || 0;
  const p = marks.tp || 0;

  // Rule: Exam is 60%, TD 20%, TP 20%
  if (config.hasTd && config.hasTp) {
    return (e * WEIGHTS.EXAM_WITH_BOTH) + (d * WEIGHTS.TD_POND) + (p * WEIGHTS.TP_POND);
  }

  // Rule: If neither TD nor TP, Exam is 100%
  if (!config.hasTd && !config.hasTp) {
    return e * WEIGHTS.EXAM_FULL;
  }

  // Rule: If no TD, Exam 60% and TP 40%
  if (!config.hasTd && config.hasTp) {
    return (e * WEIGHTS.EXAM_WITH_BOTH) + (p * WEIGHTS.DUO_POND_SECONDARY);
  }

  // Rule: If no TP, Exam 60% and TD 40%
  if (config.hasTd && !config.hasTp) {
    return (e * WEIGHTS.EXAM_WITH_BOTH) + (d * WEIGHTS.DUO_POND_SECONDARY);
  }

  return 0;
};

export const getStatusColor = (average: number): string => {
  if (average >= 14) return 'text-emerald-600 bg-emerald-50 border-emerald-200';
  if (average >= 10) return 'text-blue-600 bg-blue-50 border-blue-200';
  if (average >= 8) return 'text-amber-600 bg-amber-50 border-amber-200';
  return 'text-rose-600 bg-rose-50 border-rose-200';
};

export const getProgressBarColor = (average: number): string => {
  if (average >= 14) return 'bg-emerald-500';
  if (average >= 10) return 'bg-blue-500';
  if (average >= 8) return 'bg-amber-500';
  return 'bg-rose-500';
};

import React from 'react';
import { ModuleConfig, ModuleMarks } from '../types';
import { calculateModuleAverage, getStatusColor } from '../utils';

interface Props {
  config: ModuleConfig;
  marks: ModuleMarks;
  onChange: (moduleId: string, part: keyof ModuleMarks, value: number) => void;
}

const ModuleCard: React.FC<Props> = ({ config, marks, onChange }) => {
  const average = calculateModuleAverage(config, marks);
  const colorClass = getStatusColor(average);

  const handleInputChange = (part: keyof ModuleMarks, val: string) => {
    const num = parseFloat(val);
    onChange(config.id, part, isNaN(num) ? 0 : Math.min(20, Math.max(0, num)));
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 transition-all hover:shadow-md">
      <div className="flex justify-between items-start mb-4">
        <div>
          <h3 className="text-lg font-bold text-slate-800 leading-tight">{config.name}</h3>
          <p className="text-xs font-medium text-slate-400 uppercase tracking-wider mt-1">
            Coefficient: {config.coefficient}
          </p>
        </div>
        <div className={`px-3 py-1 rounded-full border text-sm font-bold ${colorClass}`}>
          {average.toFixed(2)}
        </div>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-xs font-semibold text-slate-500 mb-1">EXAMEN (60%)</label>
          <input
            type="number"
            min="0"
            max="20"
            step="0.25"
            value={marks.exam || ''}
            onChange={(e) => handleInputChange('exam', e.target.value)}
            className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            placeholder="Note / 20"
          />
        </div>

        {config.hasTd && (
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1">TD {config.hasTp ? '(20%)' : '(40%)'}</label>
            <input
              type="number"
              min="0"
              max="20"
              step="0.25"
              value={marks.td || ''}
              onChange={(e) => handleInputChange('td', e.target.value)}
              className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
              placeholder="Note / 20"
            />
          </div>
        )}

        {config.hasTp && (
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-1">TP {config.hasTd ? '(20%)' : '(40%)'}</label>
            <input
              type="number"
              min="0"
              max="20"
              step="0.25"
              value={marks.tp || ''}
              onChange={(e) => handleInputChange('tp', e.target.value)}
              className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
              placeholder="Note / 20"
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default ModuleCard;

import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer } from 'recharts';
import { ModuleConfig, SemesterState } from '../types';
import { calculateModuleAverage, getProgressBarColor } from '../utils';

interface Props {
  modules: ModuleConfig[];
  state: SemesterState;
}

const Summary: React.FC<Props> = ({ modules, state }) => {
  let totalWeightedAverage = 0;
  let totalCoefficients = 0;

  modules.forEach((mod) => {
    const avg = calculateModuleAverage(mod, state[mod.id] || {});
    totalWeightedAverage += avg * mod.coefficient;
    totalCoefficients += mod.coefficient;
  });

  const semesterAverage = totalCoefficients > 0 ? totalWeightedAverage / totalCoefficients : 0;
  const isPassing = semesterAverage >= 10;
  const progressColor = getProgressBarColor(semesterAverage);

  const data = [
    { name: 'Average', value: semesterAverage },
    { name: 'Remaining', value: Math.max(0, 20 - semesterAverage) },
  ];

  return (
    <div className="bg-indigo-900 text-white rounded-3xl p-8 shadow-xl mb-8 sticky top-4 z-10 overflow-hidden">
      {/* Background Decoration */}
      <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-indigo-800 rounded-full opacity-50 blur-3xl"></div>
      <div className="absolute bottom-0 left-0 -ml-16 -mb-16 w-64 h-64 bg-indigo-700 rounded-full opacity-30 blur-3xl"></div>

      <div className="relative flex flex-col md:flex-row items-center justify-between gap-8">
        <div className="flex-1 text-center md:text-left">
          <h2 className="text-indigo-200 font-semibold uppercase tracking-widest text-sm mb-2">Moyenne du Semestre</h2>
          <div className="flex items-baseline gap-2 justify-center md:justify-start">
            <span className="text-6xl font-black tracking-tighter">{semesterAverage.toFixed(2)}</span>
            <span className="text-2xl font-medium text-indigo-300">/ 20</span>
          </div>
          <div className="mt-4 inline-flex items-center px-4 py-1.5 rounded-full bg-white/10 backdrop-blur-sm border border-white/20">
            <span className={`w-2.5 h-2.5 rounded-full mr-2 ${isPassing ? 'bg-emerald-400' : 'bg-rose-400'}`}></span>
            <span className="text-sm font-bold uppercase">
              {isPassing ? 'Semestre Validé' : 'Semestre Non Validé'}
            </span>
          </div>
        </div>

        <div className="w-48 h-48 relative flex items-center justify-center">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={data}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={0}
                  dataKey="value"
                  startAngle={90}
                  endAngle={450}
                >
                  <Cell fill="currentColor" className={progressColor.replace('bg-', 'text-')} />
                  <Cell fill="rgba(255,255,255,0.1)" />
                </Pie>
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex items-center justify-center flex-col">
              <span className="text-xs text-indigo-300 uppercase font-bold">Progression</span>
              <span className="text-xl font-bold">{Math.round((semesterAverage / 20) * 100)}%</span>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Summary;

import React, { useState, useEffect } from 'react';
import { MODULES } from './constants';
import { SemesterState, ModuleMarks } from './types';
import ModuleCard from './components/ModuleCard';
import Summary from './components/Summary';

const App: React.FC = () => {
  const [semesterState, setSemesterState] = useState<SemesterState>(() => {
    const saved = localStorage.getItem('semester_marks');
    return saved ? JSON.parse(saved) : {};
  });

  useEffect(() => {
    localStorage.setItem('semester_marks', JSON.stringify(semesterState));
  }, [semesterState]);

  const handleMarkChange = (moduleId: string, part: keyof ModuleMarks, value: number) => {
    setSemesterState((prev) => ({
      ...prev,
      [moduleId]: {
        ...(prev[moduleId] || {}),
        [part]: value,
      },
    }));
  };

  const resetAll = () => {
    if (confirm('Voulez-vous vraiment réinitialiser toutes les notes ?')) {
      setSemesterState({});
    }
  };

  return (
    <div className="min-h-screen pb-12">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 pt-8">
        <header className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-black text-slate-900">Calculateur <span className="text-indigo-600">Moyenne</span></h1>
            <p className="text-slate-500 font-medium">Gestion et suivi de votre semestre universitaire</p>
          </div>
          <button
            onClick={resetAll}
            className="px-6 py-2.5 bg-white border border-slate-200 text-slate-600 font-bold rounded-xl hover:bg-slate-50 hover:text-rose-600 hover:border-rose-200 transition-all shadow-sm flex items-center gap-2"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" />
            </svg>
            Réinitialiser
          </button>
        </header>

        <Summary modules={MODULES} state={semesterState} />

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {MODULES.map((module) => (
