          ))}
        </div>

        <footer className="mt-16 text-center text-slate-400 text-sm font-medium">
          <p>Règles de calcul : Exam (60%), TD (20%), TP (20%)</p>
          <p className="mt-1">Pondération dynamique selon la disponibilité des épreuves de TD/TP.</p>
        </footer>
      </div>
    </div>
  );
};

export default App;

