import React from 'react';
import { ModuleConfig, ModuleMarks } from '../types.ts';
import { calculateModuleAverage, getStatusColor } from '../utils.ts';

interface Props {
  config: ModuleConfig;
  marks: ModuleMarks;
  onChange: (moduleId: string, part: keyof ModuleMarks, value: number) => void;
}

const ModuleCard: React.FC<Props> = ({ config, marks, onChange }) => {
  const average = calculateModuleAverage(config, marks);
  const statusColor = getStatusColor(average);

  const handleInputChange = (part: keyof ModuleMarks, val: string) => {
    if (val === "") {
        onChange(config.id, part, undefined as any);
        return;
    }
    const num = parseFloat(val);
    const safeNum = isNaN(num) ? 0 : Math.min(20, Math.max(0, num));
    onChange(config.id, part, safeNum);
  };

  const inputStyle = "w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:bg-white outline-none transition-all text-slate-900 font-bold text-lg placeholder:text-slate-300 placeholder:font-normal";

  // Label helpers
  const getWeightLabel = (part: 'exam' | 'td' | 'tp') => {
    if (part === 'exam') {
      if (!config.hasTd && !config.hasTp) return "100%";
      return "60%";
    }
    if (part === 'td') return config.hasTp ? "20%" : "40%";
    if (part === 'tp') return config.hasTd ? "20%" : "40%";
    return "";
  };

  return (
    <div className="group bg-white rounded-3xl shadow-sm border border-slate-200 p-6 hover:shadow-xl hover:border-indigo-100 transition-all duration-300">
      <div className="flex justify-between items-start mb-6">
        <div>
          <h3 className="text-xl font-bold text-slate-800 group-hover:text-indigo-900 transition-colors">{config.name}</h3>
          <span className="inline-block px-2 py-0.5 mt-1 bg-slate-100 text-slate-500 text-[10px] font-black uppercase tracking-tighter rounded-md">
            Coefficient {config.coefficient}
          </span>
        </div>
        <div className={`flex flex-col items-end`}>
          <span className={`text-2xl font-black tabular-nums ${statusColor.split(' ')[0]}`}>
            {average.toFixed(2)}
          </span>
          <span className="text-[10px] font-bold text-slate-400 uppercase">Moyenne</span>
        </div>
      </div>

      <div className="space-y-5">
        <div className="relative">
          <div className="flex justify-between mb-1.5 px-1">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Examen</label>
            <span className="text-[10px] font-bold text-indigo-400">{getWeightLabel('exam')}</span>
          </div>
          <input
            type="number"
            value={marks.exam ?? ''}
            onChange={(e) => handleInputChange('exam', e.target.value)}
            className={inputStyle}
            placeholder="Note / 20"
          />
        </div>

        {config.hasTd && (
          <div className="relative">
            <div className="flex justify-between mb-1.5 px-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">TD</label>
              <span className="text-[10px] font-bold text-indigo-400">{getWeightLabel('td')}</span>
            </div>
            <input
              type="number"
              value={marks.td ?? ''}
              onChange={(e) => handleInputChange('td', e.target.value)}
              className={inputStyle}
              placeholder="Note / 20"
            />
          </div>
        )}

        {config.hasTp && (
          <div className="relative">
            <div className="flex justify-between mb-1.5 px-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">TP</label>
              <span className="text-[10px] font-bold text-indigo-400">{getWeightLabel('tp')}</span>
            </div>
            <input
              type="number"
              value={marks.tp ?? ''}
              onChange={(e) => handleInputChange('tp', e.target.value)}
              className={inputStyle}
              placeholder="Note / 20"
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default ModuleCard;

