  if (average >= 16) return 'bg-emerald-500 text-white border-emerald-400 shadow-emerald-100';
  if (average >= 12) return 'bg-indigo-500 text-white border-indigo-400 shadow-indigo-100';
  if (average >= 10) return 'bg-sky-500 text-white border-sky-400 shadow-sky-100';
  if (average >= 8) return 'bg-amber-500 text-white border-amber-400 shadow-amber-100';
  return 'bg-rose-500 text-white border-rose-400 shadow-rose-100';
};

